   183			if cert.NeedsRenewal(cm) {
   184				renew = append(renew, domain)
   185				needsReload = true
   186			}
   187			if mgr.ocspCache.updated(domain, cert.OCSPStaple) {
   188				ocsp = append(ocsp, domain)
   189				needsReload = true
   190			}
   191		}
   192		if !needsReload {
   193			return nil
   194		}
   195	
   196		ctx = log.WithContext(ctx, func(c zerolog.Context) zerolog.Context {
   197			if len(renew) > 0 {
   198				c = c.Strs("renew_domains", renew)
   199			}
   200			if len(ocsp) > 0 {
   201				c = c.Strs("ocsp_refresh", ocsp)
   202			}
   203			return c
   204		})
   205		log.Info(ctx).Msg("updating certificates")
   206	
   207		cfg = mgr.src.GetConfig().Clone()
   208		mgr.updateServer(ctx, cfg)
   209		if err := mgr.updateAutocert(ctx, cfg); err != nil {
   210			return err
   211		}
   212	
   213		mgr.config = cfg
   214		mgr.Trigger(ctx, cfg)
   215		return nil
   216	}
