   218	func (mgr *Manager) update(ctx context.Context, cfg *config.Config) error {
   219		cfg = cfg.Clone()
   220	
   221		mgr.mu.Lock()
   222		defer mgr.mu.Unlock()
   223		defer func() { mgr.config = cfg }()
   224	
   225		mgr.updateServer(ctx, cfg)
   226		return mgr.updateAutocert(ctx, cfg)
   227	}
