   349	// configureCertificateAuthority configures the acmeMgr ACME Certificate Authority settings.
   350	func configureCertificateAuthority(acmeMgr *certmagic.ACMEIssuer, opts config.AutocertOptions) error {
   351		acmeMgr.Agreed = true
   352		if opts.UseStaging {
   353			acmeMgr.CA = acmeMgr.TestCA
   354		}
   355		if opts.CA != "" {
   356			acmeMgr.CA = opts.CA // when a CA is specified, it overrides the staging setting
   357		}
   358		if opts.Email != "" {
   359			acmeMgr.Email = opts.Email
   360		}
   361		return nil
   362	}
