   364	// configureExternalAccountBinding configures the acmeMgr ACME External Account Binding settings.
   365	func configureExternalAccountBinding(acmeMgr *certmagic.ACMEIssuer, opts config.AutocertOptions) error {
   366		if opts.EABKeyID != "" || opts.EABMACKey != "" {
   367			acmeMgr.ExternalAccount = &acme.EAB{}
   368		}
   369		if opts.EABKeyID != "" {
   370			acmeMgr.ExternalAccount.KeyID = opts.EABKeyID
   371		}
   372		if opts.EABMACKey != "" {
   373			_, err := base64.RawURLEncoding.DecodeString(opts.EABMACKey)
   374			if err != nil {
   375				return fmt.Errorf("config: decoding base64-urlencoded MAC Key: %w", err)
   376			}
   377			acmeMgr.ExternalAccount.MACKey = opts.EABMACKey
   378		}
   379		return nil
   380	}
