   382	// configureTrustedRoots configures the acmeMgr x509 roots to trust when communicating with an ACME CA.
   383	func configureTrustedRoots(acmeMgr *certmagic.ACMEIssuer, opts config.AutocertOptions) error {
   384		if opts.TrustedCA != "" {
   385			// pool effectively contains the certificate(s) in the TrustedCA base64 PEM appended to the system roots
   386			pool, err := cryptutil.GetCertPool(opts.TrustedCA, "")
   387			if err != nil {
   388				return fmt.Errorf("config: creating trusted certificate pool: %w", err)
   389			}
   390			acmeMgr.TrustedRoots = pool
